private long currentVersion(long windowId) throws Exception {
    return getOk("/api/windows/" + windowId + "/reserve").get("version").asLong();
}

private Map<String, Object> transferBody(String commandKey, String transferKey,
                                         String sourceKey, String targetKey) {
    // 默认每次携带调用前最新窗口版本（窗口初始版本 0，每次转让成功后自增）
    return transferBody(commandKey, transferKey, sourceKey, targetKey, 0L, true);
}

private Map<String, Object> transferBody(String commandKey, String transferKey,
                                         String sourceKey, String targetKey, long expectedVersion,
                                         boolean refreshVersion) {
    long version = expectedVersion;
    if (refreshVersion) {
        try {
            version = currentVersion(windowOfTransfer(sourceKey));
        } catch (Exception e) {
            throw new IllegalStateException(e);
        }
    }
    Map<String, Object> body = new HashMap<>();
    body.put("commandKey", commandKey);
    body.put("transferKey", transferKey);
    body.put("sourceAllocationKey", sourceKey);
    body.put("targetAllocationKey", targetKey);
    body.put("reserveKey", key("rk"));
    body.put("expectedVersion", version);
    return body;
}

private long windowOfTransfer(String sourceKey) {
    // 测试内全部转让集中在单一窗口，调用方仅在单窗口场景使用默认辅助，改用显式 windowId 更稳妥
    throw new UnsupportedOperationException("use transferBody(windowId, ...)");
}

private Map<String, Object> transferBody(long windowId, String commandKey, String transferKey,
                                         String sourceKey, String targetKey) {
    long version;
    try {
        version = currentVersion(windowId);
    } catch (Exception e) {
        throw new IllegalStateException(e);
    }
    Map<String, Object> body = new HashMap<>();
    body.put("commandKey", commandKey);
    body.put("transferKey", transferKey);
    body.put("sourceAllocationKey", sourceKey);
    body.put("targetAllocationKey", targetKey);
    body.put("reserveKey", key("rk"));
    body.put("expectedVersion", version);
    return body;
}

private int transferStatus(String commandKey, String transferKey, String sourceKey,
                           String targetKey, String actor) {
    return transferStatus(commandKey, transferKey, sourceKey, targetKey, actor, 0L, false);
}

private int transferStatus(long windowId, String commandKey, String transferKey, String sourceKey,
                           String targetKey, String actor) {
    long version;
    try {
        version = currentVersion(windowId);
    } catch (Exception e) {
        throw new IllegalStateException(e);
    }
    return transferStatus(commandKey, transferKey, sourceKey, targetKey, actor, version, false);
}

private int transferStatus(String commandKey, String transferKey, String sourceKey,
                           String targetKey, String actor, long expectedVersion,
                           boolean ignoredRefreshFlag) {
    try {
        waterService.transferAllocation(commandKey, transferKey, sourceKey, targetKey, actor,
                key("rk"), expectedVersion);
        return 200;
    } catch (ApiException e) {
        return e.status().value();
    }
}

