        // 总配额 10、已批准持有 6、储备 4；限供到 8（>=储备 4 且 >=已批准 6，合法），
        // 此后常规池 = 8-4 = 4 < 持有 6，新常规转让/常规核销必须 422。
        long windowId = createWindow("ch-blk-" + run, "2026-10-23T00:00:00Z", "2026-10-23T02:00:00Z", "10");
