        // 同键改数量（指纹变化）-> 409
        postJson("/api/windows/" + windowId + "/writeoffs/emergency",
                emergencyBatchBody(rk, 1L, List.of(emergencyItem("em-x", "chief", "2"))),
                "alice", 409);

        // 储备调整同键同指纹重放
        String adjustKey = key("rk");
