        JsonNode c1 = postOk("/api/windows/" + windowId + "/close", closeBody, "dispatcher");
        JsonNode c2 = postOk("/api/windows/" + windowId + "/close", closeBody, "dispatcher");
        assertEquals(c1, c2);
        assertEquals("CLOSED", c2.get("status").asText());
    }

